cd /tmp/sv-b33291ea5f98428e89c25459d9d6cafa/moderate-msbuild-properties && dotnet package list --format json 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)
for p in data['projects']:
    name = p['path'].rsplit('/',1)[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
"

